            try {
                $items = Get-ChildItem -Path $target.Path -Recurse -ErrorAction SilentlyContinue
                $count = $items.Count
                $size = ($items | Measure-Object -Property Length -Sum).Sum / 1MB

                Remove-Item -Path $target.Path -Recurse -Force -ErrorAction SilentlyContinue

                $totalDeleted += $count
