    )
    [Console]::Error.WriteLine("[$( Get-Date -Format 'yyyy-MM-dd HH:mm:ss.fff')][$Phase][$Level] $Message")
    if ($null -ne ${script:AutonomousAgentState}) {
        ${script:AutonomousAgentState}.CurrentOperation = $Message
