        elseif ($Level -eq 'Warning')      { ${script:AutonomousAgentState}.Warnings.Add($Message) }
        ${script:AutonomousAgentState}.LearningHistory.Add(@{
            Timestamp = Get-Date -Format 'yyyy-MM-dd HH:mm:ss.fff'
            Level     = $Level
            Message   = $Message
            Data      = $Data
        })
    }
}

